import { api } from "../api.js";
import { go, screenWrap } from "../router.js";
import { startAnalysis } from "../screens/analyse.js";
import { openChart } from "../screens/chart.js";
import { loadLibrary } from "../screens/library.js";
import { S } from "../state.js";
import { SERIF, SZ, T, UI, clear, el, fmt, kitIcon, kitLegend, kitSegmented, note, resetSpelling, toast } from "../ui/kit.js";

// The single DOM host div (`<div id="app">`) — there is exactly one call
// site, `window.APP.build(document.getElementById("app"))` in main.js, so
// every module that touches the screen host just looks it up itself rather
// than threading a mutable binding through every import (see sprint 16-19
// report: root/S design choice).
const root = document.getElementById("app");


  // ── l'écran de recherche à trois sources (delta2 §9 / design 6a) ─────────
  // Une source à la fois, choisie en haut, YouTube par défaut. La ligne sous
  // le sélecteur dit ce que la source IMPLIQUE, parce que les trois ne font
  // pas du tout la même chose: YouTube écoute l'audio et déduit la grille
  // (une minute d'attente, un écran de chargement); iReal et les tablatures
  // importent une grille déjà écrite par un humain et s'ouvrent directement.
export const SOURCES=[
    {id:"youtube", label:"YouTube",     swatch:()=>T.accent,
     note:"Harmonia écoute l'audio et déduit la grille"},
    {id:"ireal",   label:"iReal Pro",   swatch:()=>T.blue,
     note:"grille transcrite par un musicien · pas d'audio, pas d'analyse"},
    {id:"tabs",    label:"Tablatures",  swatch:()=>T.green,
     note:"accords relevés à la main sur les sites de tablatures"}
  ];
export function renderSearch(){
    resetSpelling();
    const w=screenWrap();
    const src=S.searchMode||"youtube";

    const bar=el("div",
      `flex:0 0 auto;display:flex;align-items:center;gap:12px;`+
      `padding:calc(6px + env(safe-area-inset-top)) 14px 12px;`);
    bar.appendChild(kitIcon("‹", ()=>go("library"), "Retour"));

    const field=el("div",
      `flex:1;min-width:0;height:48px;border-radius:14px;background:${T.card};`+
      `border:1.5px solid ${T.accent};display:flex;align-items:center;gap:9px;padding:0 14px;`);
    field.appendChild(el("span",`font:400 16px ${UI};color:${T.faint};`,"⌕"));
    const inp=el("input",
      `flex:1;min-width:0;border:none;background:none;outline:none;`+
      `font:500 15px ${UI};color:${T.ink};`);
    inp.placeholder="Un titre, un artiste, un lien YouTube";
    inp.value=S.searchQuery||"";
    inp.setAttribute("enterkeyhint","search");
    inp.onkeydown=e=>{ if(e.key==="Enter"){ inp.blur(); runSearch(inp.value); } };
    field.appendChild(inp);
    if(S.searchQuery || (S.results||[]).length){
      const clr=kitIcon("×", ()=>{ S.searchQuery=""; S.results=[]; go("search",{push:false}); }, "Effacer");
      clr.style.width="32px"; clr.style.height="32px"; clr.style.border="none";
      clr.style.background="none"; clr.style.color=T.faint; clr.style.font="400 18px "+UI;
      /* exception assumée au 44 (la SEULE, cf. acceptance delta2 §1): le ×
         vit DANS un champ de 48px dont toute la surface est déjà tapable
         pour placer le curseur. Lui donner 44 mangerait la moitié du champ. */
      field.appendChild(clr);
    }
    bar.appendChild(field);
    w.appendChild(bar);

    // le sélecteur de source + ce qu'il implique
    const pick=el("div",`flex:0 0 auto;padding:0 14px 12px;`);
    pick.appendChild(kitSegmented(
      SOURCES.map(s=>[s.id, s.label]),
      ()=>S.searchMode||"youtube",
      v=>{ S.searchMode=v; S.results=[];
           try{ localStorage.setItem("harmSearchMode", v); }catch(e){}
           go("search",{push:false});
           if(S.searchQuery) runSearch(S.searchQuery); },
      {height:SZ.control}));
    const S_=SOURCES.find(s=>s.id===src)||SOURCES[0];
    pick.appendChild(kitLegend(S_.swatch(), S_.note));
    w.appendChild(pick);

    const body=el("div",
      `flex:1;min-height:0;overflow-y:auto;padding:0 14px calc(20px + env(safe-area-inset-bottom));`);
    body.className="ap-scroll"; w.appendChild(body);
    S._searchBody=body;
    paintResults();
    setTimeout(()=>{ if(!S.searchQuery) inp.focus(); },120);
    return w;
  }
// ── recherches récentes (UX #43, audit F5) ───────────────────────────────────
// Par appareil, jamais envoyées au serveur. Les liens collés n'y entrent pas :
// ils partent directement en analyse et ne se « re-cherchent » pas.
export const RECENTES_KEY="harmRecherches";
export function lireRecentes(){
    try{ const a=JSON.parse(localStorage.getItem(RECENTES_KEY)||"[]");
         return Array.isArray(a) ? a.filter(x=>typeof x==="string").slice(0,8) : []; }
    catch(e){ return []; }
  }
export function noterRecente(q){
    try{
      const a=lireRecentes().filter(x=>x.toLowerCase()!==q.toLowerCase());
      a.unshift(q); localStorage.setItem(RECENTES_KEY, JSON.stringify(a.slice(0,8)));
    }catch(e){}
  }
export async function runSearch(q){
    q=(q||"").trim(); if(!q) return;
    // les collages restent des raccourcis (flux historiques, gardés): un lien
    // YouTube part direct en analyse, un irealb:// s'importe direct
    if(/youtu\.?be/.test(q)){ startAnalysis(q, "ton lien YouTube"); return; }
    if(/^irealb:\/\//i.test(q)){ importIrealChart({irealb_url:q}); return; }
    noterRecente(q);
    S.searchQuery=q; S.searching=true; S.searchPage=0; S.searchMore=false; paintResults();
    const src=S.searchMode||"youtube";
    try{
      if(src==="ireal"){
        await irealSearchStream(q);
      } else if(src==="tabs"){
        const r=await api.post("/api/tab-search",{q});
        S.results=(r.results||[]).map(x=>({...x,_src:"tabs"}));
      } else {
        const r=await api.post("/api/yt-search",{q,page:0});
        S.results=(r.results||[]).map(x=>({...x,_src:"youtube"}));
        S.searchMore=!!r.hasMore;
      }
    }catch(e){ S.results=[]; }
    S.searching=false; paintResults();
  }
  // ── la recherche iReal arrive AU FUR ET À MESURE ─────────────────────────
  // Louis, 2026-09-18. Les deux sources n'ont pas du tout le même rythme :
  // les ~2200 standards sont prêts en 0,4 s (une page), le forum met 4 à 6 s
  // (jusqu'à six fils, espacés par politesse). En un seul bloc, l'écran
  // restait vide six secondes pour un premier résultat déjà là depuis la
  // première demi-seconde. Le serveur rend donc une ligne JSON par lot
  // (NDJSON) et on repeint à chaque ligne.
  // Repli: un navigateur sans `res.body` (flux de fetch) retombe sur la route
  // d'un seul bloc — le résultat est le même, seulement moins vivant.
export async function irealSearchStream(q){
    const ajoute=lot=>{
      if(!lot || !lot.length) return;
      const vus=new Set((S.results||[]).map(r=>(r.title||"").toLowerCase()));
      lot.forEach(x=>{ const k=(x.title||"").toLowerCase();
        if(!vus.has(k)){ vus.add(k); S.results.push({...x,_src:"ireal"}); } });
      paintResults();
    };
    S.results=[];
    const res=await fetch("/api/irealb-search-stream",
      {method:"POST",headers:{"Content-Type":"application/json"},
       body:JSON.stringify({title:q})});
    if(!res.ok) throw new Error(await res.text());
    if(!res.body || !res.body.getReader){
      const r=await api.post("/api/irealb-search",{title:q});
      ajoute(r.results||[]); return;
    }
    const lecteur=res.body.getReader(), dec=new TextDecoder();
    let reste="";
    for(;;){
      const {done,value}=await lecteur.read();
      if(done) break;
      reste+=dec.decode(value,{stream:true});
      // La dernière tranche peut couper une ligne en deux: on ne garde que
      // les lignes ENTIÈRES et on remet le reste de côté.
      const lignes=reste.split("\n"); reste=lignes.pop();
      for(const l of lignes){
        if(!l.trim()) continue;
        let d; try{ d=JSON.parse(l); }catch(e){ continue; }
        // La recherche en cours a changé sous nos pieds (il a retapé): on
        // laisse tomber ce flux-là plutôt que d'y mélanger ses résultats.
        if(S.searchQuery!==q) return;
        if(d.results) ajoute(d.results);
      }
    }
  }

  // ── importer une grille iReal ────────────────────────────────────────────
  // Le pendant de `startAnalysis` pour la source iReal : rien à écouter,
  // rien à déduire, une seule requête et le chart est là. `search.js`
  // l'appelait déjà depuis `runSearch` (collage d'une URL `irealb://`)
  // alors que la fonction n'a JAMAIS existé — la source iReal ne pouvait
  // ouvrir aucun morceau depuis sa mise en place.
export async function importIrealChart(r){
    const url=(r&&r.irealb_url)||""; if(!url) return;
    S.searchQuery=S.searchQuery||(r&&r.title)||"";
    S.searching=true; paintResults();
    try{
      const res=await api.post("/api/irealb-import",
        {irealb_url:url, composer:(r&&r.composer)||""});
      S.searching=false;
      // La bibliothèque est rechargée AVANT d'ouvrir: sans ça le retour
      // depuis le chart affiche une liste où le morceau qu'on vient
      // d'importer n'est pas.
      await loadLibrary();
      toast((res.title||"Grille")+" · "+res.nBars+" mesures");
      openChart(res.file);
    }catch(e){
      S.searching=false; paintResults();
      toast("Cette grille iReal n'a pas pu être importée");
    }
  }
export function searchCard(r){
    /* LA CARTE ENTIÈRE est la cible (≈362×67). La pastille colorée est une
       ÉTIQUETTE, pas un bouton: ne lui câble pas de onclick, elle fait 38px
       et violerait la règle des 44. */
    const card=el("div",
      `border-radius:14px;background:${T.card};border:1px solid ${T.line};`+
      `padding:12px 14px;display:flex;align-items:center;gap:12px;cursor:pointer;`);
    const tx=el("div","flex:1;min-width:0;");
    tx.appendChild(el("div",
      `font:600 15.5px ${UI};color:${T.ink};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;`,
      r.title||""));
    tx.appendChild(el("div",`font:500 12.5px ${UI};color:${T.faint};margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;`,
      r._src==="ireal" ? [r.composer,r.style,r.time_sig].filter(Boolean).join(" · ")
      : r._src==="tabs" ? [r.artist,r.rating?(r.rating+"/5"):null,r.kind].filter(Boolean).join(" · ")
      : [r.uploader, r.duration?fmt(r.duration):null].filter(Boolean).join(" · ")));
    card.appendChild(tx);

    const here=!!r.local;
    const pill=el("div",
      `flex:0 0 auto;height:38px;padding:0 14px;border-radius:12px;`+
      `display:flex;align-items:center;font:600 13px ${UI};`+
      (here ? `border:1.5px solid ${T.green};color:${T.green};`
            : `background:${T.accent};color:#fff;`),
      here ? "Déjà là"
           : (r._src==="youtube" ? "Analyser"
           : (r._src==="ireal" ? "Importer" : "Voir")));
    pill.setAttribute("aria-hidden","true");
    card.appendChild(pill);

    card.onclick=()=>{
      // Une tablature ne s'importe plus (route retirée, décision du
      // 2026-09-14) : on l'ouvre, c'est tout ce qu'elle vaut ici.
      if(r._src==="tabs"){ if(r.url) window.open(r.url,"_blank","noopener"); return; }
      // Une grille iReal s'IMPORTE — elle est déjà écrite, il n'y a rien à
      // analyser. Jusqu'au 2026-09-18 elle tombait ici dans la branche
      // YouTube et partait analyser `watch?v=undefined`.
      if(r._src==="ireal"){ importIrealChart(r); return; }
      startAnalysis(r.local ? ("local:"+String(r.id).replace(/^local:/,""))
                            : ("https://www.youtube.com/watch?v="+r.id), r.title);
    };
    return card;
  }
// L'écran vide ne reste pas vide : un conseil (le lien YouTube marche, et
// personne ne le sait) puis les dernières recherches, une ligne chacune.
function videRecentes(body){
    const hint=el("div",
      `font:italic 14px/1.6 ${SERIF};color:${T.faint};padding:6px 6px 14px;`,
      "Astuce : colle un lien YouTube dans le champ, la chanson s’analyse directement.");
    hint.dataset.astuce="lien"; body.appendChild(hint);
    const rec=lireRecentes(); if(!rec.length) return;
    const h=el("div","display:flex;align-items:center;justify-content:space-between;margin:6px 4px 6px;");
    h.appendChild(el("span",
      `font:700 11px ${UI};letter-spacing:.08em;text-transform:uppercase;color:${T.faint};`,"Récentes"));
    const eff=el("button",
      `border:none;background:none;min-height:${SZ.control}px;padding:0 4px;margin:-12px -4px;`+
      `font:600 13px ${UI};color:${T.accent};cursor:pointer;`,"Effacer");
    eff.onclick=()=>{ try{ localStorage.removeItem(RECENTES_KEY); }catch(e){} paintResults(); };
    h.appendChild(eff); body.appendChild(h);
    const list=el("div","display:flex;flex-direction:column;gap:8px;");
    rec.forEach(q=>{
      const row=el("div",
        `min-height:${SZ.control}px;border-radius:14px;background:${T.card};border:1px solid ${T.line};`+
        `display:flex;align-items:center;gap:10px;padding:0 14px;cursor:pointer;`);
      row.dataset.recente=q;
      row.appendChild(el("span",`font:400 16px ${UI};color:${T.rule};`,"⌕"));
      row.appendChild(el("span",
        `flex:1;min-width:0;font:500 15px ${UI};color:${T.ink};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;`,q));
      row.onclick=()=>{ S.searchQuery=q; S.results=[]; go("search",{push:false}); runSearch(q); };
      list.appendChild(row);
    });
    body.appendChild(list);
  }
export function paintResults(){
    const body=S._searchBody; if(!body) return;
    clear(body);

    // LE SABLIER NE CACHE PLUS CE QUI EST DÉJÀ ARRIVÉ (2026-09-18). La
    // recherche iReal rend ses résultats en plusieurs vagues; tant que
    // `S.searching` masquait tout, le flux ne servait à rien côté écran.
    const attente=()=>{
      const wrap=el("div","display:flex;align-items:center;justify-content:center;gap:10px;padding:40px 0;");
      wrap.appendChild(el("div",
        `width:18px;height:18px;border-radius:50%;border:2px solid ${T.line};`+
        `border-top-color:${T.accent};animation:ap-spin .8s linear infinite;`));
      wrap.appendChild(el("div",`font:500 14px ${UI};color:${T.faint};`,"…"));
      return wrap;
    };
    if(S.searching && !(S.results||[]).length){ body.appendChild(attente()); return; }
    if(!(S.results||[]).length){
      if(S.searchQuery) body.appendChild(el("div",
        `font:italic 13.5px/1.7 ${SERIF};color:${T.faint};padding:28px 6px;text-align:center;`,
        "rien trouvé — essaie le nom de l'artiste"));
      else videRecentes(body);
      return;
    }

    body.appendChild(el("div",
      `font:700 11px ${UI};letter-spacing:.08em;text-transform:uppercase;color:${T.faint};margin:6px 4px 10px;`,
      "Résultats"));
    const list=el("div","display:flex;flex-direction:column;gap:8px;");
    S.results.forEach(r=>list.appendChild(searchCard(r)));
    body.appendChild(list);
    // encore en train de chercher, mais il y a déjà de quoi lire
    if(S.searching){
      const w=attente(); w.style.padding="18px 0";
      w.lastChild.textContent="on cherche encore…";
      body.appendChild(w);
    }
    // scroll infini YouTube (Louis 2026-08-04) — gardé de l'ancien écran,
    // même sentinelle, mêmes gardes
    if(S.searchMore && (S.searchMode||"youtube")==="youtube"){
      const sent=el("div",`height:36px;display:flex;align-items:center;justify-content:center;font:500 11px ${UI};color:${T.faint};`,"…");
      body.appendChild(sent);
      try{
        const io=new IntersectionObserver(es=>{
          if(es.some(e=>e.isIntersecting)){
            loadMoreResults(list, x=>searchCard({...x,_src:"youtube"})).then(()=>{
              if(!S.searchMore){ io.disconnect(); sent.remove(); } });
          }
        },{rootMargin:"600px"});
        io.observe(sent);
      }catch(e){ sent.remove(); }
    }
  }
  // Infinite scroll (Louis, 2026-08-04: "il devrait y avoir un scroll
  // infini"). Guarded by S.searchLoading so a fast scroll can't fire the same
  // page twice, and it appends in place rather than re-rendering the screen —
  // go("library") would scroll the list back to the top mid-read.
  // `mkRow` reste un paramètre (delta2: c'est paintResults qui passe
  // searchCard) — l'ancienne version référençait une fonction hors de portée
  // et le catch avalait le ReferenceError en un silencieux « plus de
  // résultats » (attrapé 2026-08-04: le fetch partait, les lignes jamais).
export async function loadMoreResults(listEl, mkRow){
    if(S.searchLoading || !S.searchMore || (S.searchMode||"youtube")!=="youtube") return;
    S.searchLoading=true;
    try{
      const r=await api.post("/api/yt-search",{q:S.searchQuery,page:S.searchPage+1});
      const more=r.results||[];
      S.searchPage+=1; S.searchMore=!!r.hasMore;
      if(more.length){
        S.results=S.results.concat(more);
        if(listEl && mkRow) more.forEach(x=>listEl.appendChild(mkRow(x)));
      }
    }catch(e){ S.searchMore=false; toast("Plus de résultats indisponibles"); }
    S.searchLoading=false;
  }

